void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec2 center = vec2 (.5,.7);
sunpos = vec2(.2,.08);
uv1 = (uv-center)*uAspect.xy;
mask = clamp01(512.0 * uv1.y);
z =1.0 / (uv1.y);
rs0.x = uv1.x * z; rs0.y = z ;
rs    = vec2 (rs0.x, rs0.y+uTime * 1.0);
water = texture(sampler_noise_hq,rs*mask) + texture(sampler_noise_hq,rs/4.0*mask+uTime / 8.0) - 1.0;
uv_wat = vec2(uv1.x, abs(uv1.y))-water/z*.25* mask; //z: mehr nahreflekt.
// S U N
sun = clamp01(.01/length(uv_wat-sunpos))*suncol;
// S K Y  B A C K G R O U N D
sky1 = .15*clamp01(.5-abs(uv1.y))*vec3 (.6,.8, 1.0 );
// C L O U D S  L A Y E R 1
uv4 = vec2 (uv_wat.x / 4.0, pow(uv_wat.y,.5));
uv4.x += fract(uTime / 131.0) * (1.0 - uv4.y);
cld1 = lum(texture(sampler_noise_mq,uv4 ));
cld1 = vec3 ( 0.0 , 0.0 , 1.0 );
// C L O U D S  F R O M  W A R P  S H A D E R
clouds = (texture(sampler_main, rs_clouds(uv_wat)));
//F O R E S T
float size = .9*uv.x;
uv5 = uv_wat / 8.0/size;
float wip = (sin(uv.x * 8.0+uTime * 1.0))* (uv1.y*uv1.y)*.004/size;
float stamm = texture(sampler_noise_lq,vec2(uv5.x / 2.0+wip+rand_preset.x,.04*uv5.y) * 8.0).r-.5;
float zweig = texture(sampler_noise_lq,vec2(uv5.x * 8.0,uv5.y * 128.0-stamm / 2.0)).r;
forest = (abs(uv5.y * 32.0/size))*(1+.5*stamm)*(1+.4*zweig);
forest = clamp01(1.0 - forest) ;
vec3 forest_col= 16.0 * fwidth(forest*sqrt(sun))*(1.0 + stamm)*size*treecol*(1.0 - mask*.5);
ret = sun+ sky1*clamp01(1.0 - lum(clouds) * 3.0)+ clouds*clouds * 8.0;
ret = ret * clamp01(1.0 - forest * 8.0) + forest_col ;
ret = ret*(1.0 - mask*.0);
ret = ret+mask*texture(sampler_noise_lq,mask*(rs0 / 4.0+water*.01)).r*.4/z;//Grund
//ret = forest;
  fragColor = vec4(ret, 1.0);
}

